import sqlite3
def kib(indexes):
    c = sqlite3.connect(':memory:'); c.execute('CREATE TABLE cats (name TEXT, fur TEXT)')
    c.executemany('INSERT INTO cats VALUES (?, ?)', [('Cat%05d' % i, 'black') for i in range(10000)])
    for k in range(indexes): c.execute('CREATE INDEX i%d ON cats (%s)' % (k, 'name' if k == 0 else 'fur'))
    return c.execute('PRAGMA page_count').fetchone()[0] * c.execute('PRAGMA page_size').fetchone()[0] / 1024
